                continue
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r + 1][nc] == color:
                    found.append((r, c, dc, color))

    # A diagonal pair touching another diagonal motif is part of the motif,
    # rather than an independent line to extend.
    kept = []
    for r, c, dc, color in found:
        cells = {(r, c), (r + 1, c + dc)}
        touching_other = False
        for rr, cc, dd, other in found:
            if other == color:
                continue
            othercells = {(rr, cc), (rr + 1, cc + dd)}
            if any(max(abs(a-x), abs(b-y)) == 1
                   for a, b in cells for x, y in othercells):
                touching_other = True
                break
        if not touching_other:
            kept.append((r, c, dc, color))

    out = [row[:] for row in grid]
    for r, c, dc, color in kept:
        rr, cc = r, c
        while 0 <= rr - 1 < h and 0 <= cc - dc < w:
            rr -= 1
            cc -= dc
        while 0 <= rr < h and 0 <= cc < w:
            if out[rr][cc] == bg:
                out[rr][cc] = color
            rr += 1
            cc += dc
    return out
