def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    pairs = []
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r + 1][nc] == color:
                    pairs.append((r, c, dc, color))

    def has_other_neighbor(r, c, color):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] not in (bg, color):
                    return True
        return False

    for r, c, dc, color in pairs:
        # Pairs forming part of a tight multicolor corner are not extended.
        if (has_other_neighbor(r, c, color) and
                has_other_neighbor(r + 1, c + dc, color)):
            continue
        rr, cc = r, c
        while 0 <= rr - 1 < h and 0 <= cc - dc < w:
            rr -= 1
            cc -= dc
        while 0 <= rr < h and 0 <= cc < w:
            if out[rr][cc] == bg:
                out[rr][cc] = color
            rr += 1
            cc += dc
    return out
